            throw new StringIndexOutOfBoundsException("Invalid startIndex: " + startIndex);
        }
        if (length < 0 || startIndex + length > chars.length) {
            throw new StringIndexOutOfBoundsException("Invalid length: " + length);
        }
        if (length > 0) {
