static String truncate(final String str, final int offset, final int maxWidth) {
        if (offset < 0) {
            throw new IllegalArgumentException("offset cannot be negative");
        }
        if (maxWidth < 0) {
            throw new IllegalArgumentException("maxWidth cannot be negative");
        }
        if (str == null) {
            return null;
        }
        final int len = str.length();
        int start = Math.min(offset, len);
        int end = Math.min(offset > len - maxWidth ? len : offset + maxWidth, len);
        // keep both edges off the middle of a surrogate pair so the result is never left holding a lone surrogate
        if (splitsSurrogatePair(str, start)) {
            start++;
        }
        if (splitsSurrogatePair(str, end)) {
            end--;
        }
        return str.substring(start, Math.max(start, end));
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

