public long nextTransition(long instant) {
    long offset = getOffset(instant);
    long next = instant + offset;
    if ((instant ^ next) < 0 && (instant ^ offset) >= 0) {
        throw new ArithmeticException("Adding offset caused overflow: " + instant + " + " + offset);
    }
