static int hashCode(final Annotation a) {
        int result = 0;
        final Class<? extends Annotation> type = a.annotationType();
        for (final Method m : type.getDeclaredMethods()) {
            try {
                AbstractReflection.setAccessible(AbstractReflection.getForceAccessible(), m);
                final Object value = m.invoke(a);
                if (value == null) {
                    throw new IllegalStateException(String.format("Annotation method %s returned null", m));
                }
                result += hashMember(m.getName(), value);
            } catch (final ReflectiveOperationException ex) {
                throw new UncheckedException(ex);
            }
        }
        return result;
    },0,commons-lang,7e5906fb0cb679d630527fc1bc18018f935518dc,src/main/java/org/apache/commons/lang3/AnnotationUtils.java

