static boolean isAlphanumericSpace(final CharSequence cs) {
        if (cs == null) {
            return false;
        }
        final int sz = cs.length();
        for (int i = 0; i < sz;) {
            final int codePoint = Character.codePointAt(cs, i);
            if (codePoint != ' ' && !Character.isLetterOrDigit(codePoint)) {
                return false;
            }
            i += Character.charCount(codePoint);
        }
        return true;
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

private boolean compliesWithUpgradePolicy(Library library, DependencyVersion candidate) {
		UpgradePolicy libraryPolicy = library.getUpgradePolicy();
		UpgradePolicy bomPolicy = this.bom.getUpgrade().getPolicy();
		UpgradePolicy upgradePolicy = UpgradePolicy.max(libraryPolicy, bomPolicy);
		return upgradePolicy.test(candidate, library.getVersion().getVersion());
	},0,spring-boot,178305c85409b61a283f101ca888f29978a248f6,buildSrc/src/main/java/org/springframework/boot/build/bom/bomr/UpgradeDependencies.java

