        assertTrue(ObjectUtils.isNotEmpty(Optional.ofNullable(new Object())));
    },0,commons-lang,a593c2f5c12c4a851908f043540e1908ede1b179,src/test/java/org/apache/commons/lang3/ObjectUtilsTest.java

