static boolean isMixedCase(final CharSequence cs) {
        if (isEmpty(cs) || cs.length() == 1) {
            return false;
        }
        boolean containsUppercase = false;
        boolean containsLowercase = false;
        final int sz = cs.length();
        for (int i = 0; i < sz;) {
            final int codePoint = Character.codePointAt(cs, i);
            if (Character.isUpperCase(codePoint)) {
                containsUppercase = true;
            } else if (Character.isLowerCase(codePoint)) {
                containsLowercase = true;
            }
            if (containsUppercase && containsLowercase) {
                return true;
            }
            i += Character.charCount(codePoint);
        }
        return false;
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

