static String center(String str, final int size, final char padChar) {
        if (str == null || size <= 0) {
            return str;
        }
        final int strLen = str.length();
        final int pads = size - strLen;
        if (pads <= 0) {
            return str;
        }
        str = leftPad(str, strLen + pads / 2, padChar);
        return rightPad(str, size, padChar);
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

