static boolean isNumeric(final CharSequence cs) {
        if (isEmpty(cs)) {
            return false;
        }
        final int sz = cs.length();
        for (int i = 0; i < sz;) {
            final int codePoint = Character.codePointAt(cs, i);
            if (!Character.isDigit(codePoint)) {
                return false;
            }
            i += Character.charCount(codePoint);
        }
        return true;
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

